// Mock transport: replaces window.fetch for the game's /api/* routes and the Agent Server routes the SPA uses, speaking the
// real wire format (SSE frames end in \r\n\r\n, Content-Location, Last-Event-ID joins, interrupt + resume by id map).
// Activated by api.js `ensureMock()` for `?mock=1` (force: nothing leaves the page) or `?mock=fallback` (try the real server first,
// simulate when it answers 404/405/5xx or is unreachable). Runs are generated by engine.js.

import { encodeSSE } from '../core/sse.js';
import { lsGet, lsSet } from '../core/store.js';
import * as D from './data.js';
import { GENERATORS, Frames, hash, deriveStatus } from './engine.js';

const enc = new TextEncoder();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clone = (x) => JSON.parse(JSON.stringify(x));
const json = (data, status = 200, headers = {}) => new Response(data === undefined || data === null ? null : JSON.stringify(data), { status, headers: { 'content-type': 'application/json', ...headers } });
const err = (status, detail) => json({ detail }, status);

const S = {
  tours: new Map(Object.entries(lsGet('mock_tours', {}))),
  threads: new Map(),
  runs: new Map(),
  n: lsGet('mock_n', 0),
};
const persist = () => {
  lsSet('mock_tours', Object.fromEntries(S.tours));
  lsSet('mock_n', S.n);
};

const uuidFrom = (...parts) => {
  const a = hash(...parts).toString(16).padStart(8, '0');
  const b = hash(...parts, 'b').toString(16).padStart(8, '0');
  const c = hash(...parts, 'c').toString(16).padStart(8, '0');
  const d = hash(...parts, 'd').toString(16).padStart(8, '0');
  return `${a}-${b.slice(0, 4)}-4${b.slice(5, 8)}-a${c.slice(1, 4)}-${c.slice(4)}${d.slice(0, 4)}`;
};

// ---------------------------------------------------------------------------------------------------------------
// tours

function newTour(seed) {
  const s = Number.isFinite(Number(seed)) && seed !== undefined && seed !== null && seed !== '' ? Number(seed) : Math.floor(Date.now() / 1000) % 100000;
  const id = `tour-${hash(s, ++S.n, Date.now() % 997).toString(16).slice(0, 4)}`;
  const pool = D.TOWNS.filter((t) => t.id !== 'wibbling_opera').sort((a, b) => hash(s, a.id) - hash(s, b.id));
  const towns = [...pool.slice(0, 4).map((t) => t.id), 'wibbling_opera'];
  const tour = { id, seed: s, night: 0, towns, funds: 8, encore: 2, candles: 2, rapport: {}, traditions: [], history: [], wagon: { at: towns[0] }, status: 'active' };
  S.tours.set(id, tour);
  persist();
  return tour;
}

const publicTour = (t) => {
  const { _cal, _crashed, ...rest } = t;
  void _cal;
  void _crashed;
  return clone({ ...rest, status: deriveStatus(t) });
};

function ghostTour(id) {
  const t = { id, seed: 0, night: 0, towns: ['marshwick', 'tickleton', 'dimmock', 'gloomhold', 'wibbling_opera'], funds: 8, encore: 2, candles: 2, rapport: {}, traditions: [], history: [], wagon: { at: 'marshwick' }, status: 'active' };
  S.tours.set(id, t);
  return t;
}

// ---------------------------------------------------------------------------------------------------------------
// threads + runs

function getThread(id) {
  let t = S.threads.get(id);
  if (!t) {
    t = { id, metadata: {}, values: {}, history: [], snapshots: {}, step: 0, cpN: 0, intN: 0, lastCp: null, pending: null, status: 'idle', created_at: new Date().toISOString(), graph: null, lastInput: null };
    S.threads.set(id, t);
  }
  return t;
}

function notify(run) {
  const w = run.waiters.splice(0);
  for (const r of w) r();
}

async function execute(run, thread, body) {
  const emit = async (event, data, dt = 1) => {
    run.frames.push({ event, data, id: `${run.t0}-${run.frames.length}` });
    notify(run);
    if (dt) await sleep(dt);
  };
  try {
    await emit('metadata', { run_id: run.run_id, attempt: 1 }, 2);
    let gen;
    let env;
    let resumeVal;
    if (body.command && body.command.resume !== undefined) {
      const p = thread.pending;
      if (!p) throw new Error('nothing to resume on this thread');
      thread.pending = null;
      gen = p.gen;
      env = p.env;
      const r = body.command.resume;
      resumeVal = r && typeof r === 'object' && p.interrupt.id in r ? r[p.interrupt.id] : r;
    } else {
      const graph = body.assistant_id;
      const make = GENERATORS[graph];
      if (!make) throw new Error(`unknown graph "${graph}"`);
      const forkCp = body.checkpoint?.checkpoint_id || body.config?.configurable?.checkpoint_id;
      const input = body.input ?? thread.lastInput ?? {};
      thread.lastInput = input;
      thread.graph = graph;
      thread.pending = null;
      if (input.tour_id && !S.tours.has(input.tour_id)) ghostTour(input.tour_id);
      env = { input, tour: S.tours.get(input.tour_id) || ghostTour(`tour-${input.tour_id || 'x'}`), thread, from: forkCp ? thread.snapshots[forkCp] || null : null };
      env.f = new Frames(env);
      if (!forkCp) thread.values = {};
      gen = make(env);
    }
    thread.status = 'running';
    let r = gen.next(resumeVal);
    while (!r.done) {
      const fr = r.value;
      if (fr && fr.interrupt) {
        const intr = [{ id: fr.interrupt.id, value: fr.interrupt.value }];
        await emit('updates', { __interrupt__: intr }, 2);
        await emit('values', { ...clone(thread.values), __interrupt__: intr }, 2);
        thread.pending = { gen, env, interrupt: fr.interrupt };
        thread.status = 'interrupted';
        run.status = 'success';
        await emit('end', null, 0);
        run.done = true;
        notify(run);
        persist();
        return;
      }
      await emit(fr.event, fr.data, fr.dt ?? 1);
      r = gen.next();
    }
    thread.status = 'idle';
    run.status = 'success';
    await emit('end', null, 0);
  } catch (e) {
    console.error('mock run failed', e);
    run.status = 'error';
    thread.status = 'error';
    await emit('error', { error: 'MockError', message: String(e?.message || e) }, 0);
    await emit('end', null, 0);
  }
  run.done = true;
  notify(run);
  persist();
}

function startRun(threadId, body) {
  const thread = getThread(threadId);
  const t0 = Date.now();
  const run = { run_id: uuidFrom('run', threadId, t0, ++S.n), thread_id: threadId, assistant_id: body.assistant_id, frames: [], done: false, status: 'running', waiters: [], t0, created_at: new Date(t0).toISOString() };
  S.runs.set(run.run_id, run);
  execute(run, thread, body);
  return run;
}

function sseResponse(run, afterIdx) {
  let i = afterIdx + 1;
  let cancelled = false;
  const stream = new ReadableStream({
    async pull(ctrl) {
      while (i >= run.frames.length && !run.done && !cancelled) await new Promise((r) => run.waiters.push(r));
      if (cancelled) return;
      if (i < run.frames.length) {
        const fr = run.frames[i++];
        ctrl.enqueue(enc.encode(encodeSSE({ event: fr.event, data: fr.data, id: fr.id })));
        return;
      }
      ctrl.close();
    },
    cancel() {
      cancelled = true;
    },
  });
  return new Response(stream, { status: 200, headers: { 'content-type': 'text/event-stream', 'content-location': `/threads/${run.thread_id}/runs/${run.run_id}`, 'cache-control': 'no-store' } });
}

// ---------------------------------------------------------------------------------------------------------------
// routes

const routes = [];
const R = (method, pattern, handler, opts = {}) => {
  const keys = [];
  const re = new RegExp('^' + pattern.replace(/:([a-z_]+)/g, (_m, k) => (keys.push(k), '([^/]+)')) + '/?$');
  routes.push({ method, re, keys, handler, ...opts });
};

R('GET', '/healthz', () => json({ ok: true, mock: true }));
R('GET', '/ok', () => json({ ok: true }));
R('GET', '/info', () => json({ version: 'mock', flags: {} }));

R('GET', '/api/boot', () => {
  const origin = location.origin;
  return json({
    version: 'mock',
    provider: 'offline',
    tracing: { enabled: false, project: 'probably-a-tragedy' },
    studio: { url: 'https://smith.langchain.com/studio/', base_link: `https://smith.langchain.com/studio/?baseUrl=${encodeURIComponent(origin)}` },
    graphs: D.GRAPH_META,
    datasets: D.datasetTable().map(({ name, rows, desc }) => ({ name, rows, desc })),
    public_base_url: origin,
  });
});
R('GET', '/api/graphs', () => json(D.GRAPH_META));
R('GET', '/api/datasets', () => json(D.datasetTable().map(({ name, rows, desc }) => ({ name, rows, desc }))));
R('GET', '/api/datasets/:name', ({ params, url }) => {
  const ds = D.datasetTable().find((d) => d.name === params.name);
  if (!ds) return err(404, `unknown dataset ${params.name}`);
  const offset = Number(url.searchParams.get('offset') || 0);
  const limit = Number(url.searchParams.get('limit') || 50);
  if (ds.object) return json({ name: ds.name, rows: 1, offset: 0, items: ds.data });
  return json({ name: ds.name, rows: ds.data.length, offset, items: ds.data.slice(offset, offset + limit) });
});

R('POST', '/api/tour', ({ body }) => json(publicTour(newTour(body?.seed))));
R('GET', '/api/tour/:id', ({ params }) => {
  const t = S.tours.get(params.id);
  return t ? json(publicTour(t)) : err(404, 'unknown tour');
});
R('POST', '/api/tour/:id/thread', ({ params, body }) => {
  const t = S.tours.get(params.id);
  if (!t) return err(404, 'unknown tour');
  return json({ thread_id: uuidFrom(params.id, body?.graph, t.night, body?.attempt ?? 0) });
});
R('POST', '/api/tour/:id/rewind', ({ params }) => {
  const t = S.tours.get(params.id);
  if (!t) return err(404, 'unknown tour');
  if (t.encore < 1) return err(409, 'No Encore tokens left');
  t.encore -= 1;
  persist();
  return json({ encore: t.encore });
});
R('POST', '/api/tour/:id/candle', ({ params }) => {
  const t = S.tours.get(params.id);
  if (!t) return err(404, 'unknown tour');
  if (t.candles < 1) return err(409, 'No candles left');
  t.candles -= 1;
  persist();
  return json({ candles: t.candles });
});
R('GET', '/api/links', ({ url }) => {
  const g = url.searchParams.get('graph');
  const tid = url.searchParams.get('thread_id');
  const base = `https://smith.langchain.com/studio/?baseUrl=${encodeURIComponent(location.origin)}`;
  return json({ studio_graph: g ? `${base}&graph=${g}` : base, studio_thread: tid ? `https://smith.langchain.com/studio/thread/${tid}?baseUrl=${encodeURIComponent(location.origin)}` : null, trace: null, trace_status: 'tracing is off (start the server with make dev TRACE=1)' });
});

// Agent Server
R('POST', '/threads', ({ body }) => {
  const id = body?.thread_id || uuidFrom('thread', ++S.n, Date.now());
  const existed = S.threads.has(id);
  const t = getThread(id);
  if (!existed || body?.if_exists === 'raise') t.metadata = body?.metadata || {};
  return json({ thread_id: id, created_at: t.created_at, updated_at: t.created_at, metadata: t.metadata, status: t.status });
});
R('POST', '/threads/search', () => json([...S.threads.values()].map((t) => ({ thread_id: t.id, metadata: t.metadata, status: t.status, created_at: t.created_at }))));
R('GET', '/threads/:id', ({ params }) => {
  const t = S.threads.get(params.id);
  return t ? json({ thread_id: t.id, metadata: t.metadata, status: t.status, created_at: t.created_at, values: t.values }) : err(404, 'Thread not found');
});
R('GET', '/threads/:id/state', ({ params }) => {
  const t = S.threads.get(params.id);
  if (!t) return err(404, 'Thread not found');
  const p = t.pending;
  return json({ values: t.values, next: p ? ['prompters_box'] : [], tasks: p ? [{ id: 'task-int', name: 'prompters_box', interrupts: [{ id: p.interrupt.id, value: p.interrupt.value }] }] : [], checkpoint: { checkpoint_id: t.lastCp }, created_at: t.created_at });
});
R('POST', '/threads/:id/history', ({ params, body }) => {
  const t = S.threads.get(params.id);
  if (!t) return err(404, 'Thread not found');
  return json(t.history.slice(0, body?.limit || 50));
});
R('POST', '/threads/:id/runs/stream', ({ params, body }) => {
  const thread = getThread(params.id);
  if (thread.status === 'running') return err(409, 'thread is busy');
  return sseResponse(startRun(params.id, body || {}), -1);
});
R('GET', '/threads/:id/runs/:rid', ({ params }) => {
  const r = S.runs.get(params.rid);
  return r ? json({ run_id: r.run_id, thread_id: r.thread_id, status: r.done ? r.status : 'running', assistant_id: r.assistant_id, created_at: r.created_at }) : err(404, 'run not found');
});
R('GET', '/threads/:id/runs/:rid/stream', ({ params, init }) => {
  const r = S.runs.get(params.rid);
  if (!r) return err(404, 'run not found');
  const lei = init?.headers?.['Last-Event-ID'] ?? init?.headers?.['last-event-id'];
  const idx = lei && lei !== '-1' ? Number(String(lei).split('-').pop()) : -1;
  return sseResponse(r, Number.isFinite(idx) ? idx : -1);
});
R('POST', '/threads/:id/runs/:rid/cancel', ({ params }) => {
  const r = S.runs.get(params.rid);
  if (r) {
    r.done = true;
    r.status = 'interrupted';
    notify(r);
  }
  return json({});
});
R('GET', '/assistants/:id/graph', ({ params }) => {
  const g = D.xrayGraph(decodeURIComponent(params.id));
  return g ? json(g) : err(404, 'graph not found');
});
R('POST', '/store/items/search', () => json({ items: [] }));

// ---------------------------------------------------------------------------------------------------------------
// install

const FALLBACK = new Set([404, 405, 501, 502, 503, 504]);
const isApiPath = (p) => p.startsWith('/api/') || /^\/(assistants|threads|store|runs|ok|healthz|info)(\/|$)/.test(p);

export function installMock({ fallback = false } = {}) {
  if (window.__mockInstalled) return;
  window.__mockInstalled = true;
  const realFetch = window.fetch.bind(window);
  window.fetch = async (input, init = {}) => {
    const url = new URL(typeof input === 'string' ? input : input.url, location.origin);
    const sameOrigin = url.origin === location.origin;
    if (!sameOrigin && !fallback) return realFetch(input, init);
    const path = url.pathname;
    if (!isApiPath(path)) return realFetch(input, init);
    const method = String(init.method || (typeof input !== 'string' && input.method) || 'GET').toUpperCase();
    const hit = routes.find((r) => r.method === method && r.re.test(path));
    if (fallback) {
      try {
        const real = await realFetch(input, init);
        if (!FALLBACK.has(real.status) || !hit) return real;
        try {
          real.body?.cancel();
        } catch {
          /* ignore */
        }
      } catch (e) {
        if (!hit) throw e;
      }
    }
    if (!hit) return err(404, `mock: no route for ${method} ${path}`);
    const m = hit.re.exec(path);
    const params = Object.fromEntries(hit.keys.map((k, i) => [k, decodeURIComponent(m[i + 1])]));
    let body = null;
    if (init.body && typeof init.body === 'string') {
      try {
        body = JSON.parse(init.body);
      } catch {
        body = null;
      }
    }
    if (!path.endsWith('/stream')) await sleep(25 + Math.random() * 45);
    try {
      return await hit.handler({ params, url, body, init });
    } catch (e) {
      console.error('mock handler failed', method, path, e);
      return err(500, String(e?.message || e));
    }
  };
  window.__mock = S;
}
